using Ginecologia.Modules.Inventario.Domain;
namespace Ginecologia.Modules.Inventario.Application;
public sealed class CreateInventoryItemUseCase(IInventoryItemRepository items) { public async Task<InventoryItemDto> ExecuteAsync(string nombre, string categoria, string unidad, int stockActual, int stockMinimo, decimal? precio, CancellationToken ct = default) { var item = InventoryItem.Create(nombre, categoria, unidad, stockActual, stockMinimo, precio); await items.AddAsync(item, ct); await items.SaveChangesAsync(ct); return InventoryItemDto.From(item); } }
public sealed class UpdateInventoryItemUseCase(IInventoryItemRepository items) { public async Task<InventoryItemDto> ExecuteAsync(Guid id, string nombre, string categoria, string unidad, int stockMinimo, decimal? precio, CancellationToken ct = default) { var item = await items.FindByIdAsync(id, ct) ?? throw new InventoryItemNotFoundException(id); item.Update(nombre, categoria, unidad, stockMinimo, precio); await items.SaveChangesAsync(ct); return InventoryItemDto.From(item); } }
public sealed class AdjustStockUseCase(IInventoryItemRepository items, IStockMovementRepository movements) { public async Task<InventoryItemDto> ExecuteAsync(Guid id, int delta, string motivo, Guid registradoPorId, CancellationToken ct = default) { var item = await items.FindByIdAsync(id, ct) ?? throw new InventoryItemNotFoundException(id); item.AjustarStock(delta, motivo); await movements.AddAsync(StockMovement.Create(item.Id, delta, motivo, item.StockActual, registradoPorId), ct); await items.SaveChangesAsync(ct); return InventoryItemDto.From(item); } }
public sealed class DeactivateInventoryItemUseCase(IInventoryItemRepository items) { public async Task<InventoryItemDto> ExecuteAsync(Guid id, CancellationToken ct = default) { var item = await items.FindByIdAsync(id, ct) ?? throw new InventoryItemNotFoundException(id); item.Desactivar(); await items.SaveChangesAsync(ct); return InventoryItemDto.From(item); } }
public sealed class ReactivateInventoryItemUseCase(IInventoryItemRepository items) { public async Task<InventoryItemDto> ExecuteAsync(Guid id, CancellationToken ct = default) { var item = await items.FindByIdAsync(id, ct) ?? throw new InventoryItemNotFoundException(id); item.Reactivar(); await items.SaveChangesAsync(ct); return InventoryItemDto.From(item); } }
public sealed class GetInventoryItemUseCase(IInventoryItemRepository items) { public async Task<InventoryItemDto?> ExecuteAsync(Guid id, CancellationToken ct = default) { var item = await items.FindByIdAsync(id, ct); return item is null ? null : InventoryItemDto.From(item); } }
public sealed class ListInventoryItemsUseCase(IInventoryItemRepository items) { public async Task<PagedInventoryResult<InventoryItemDto>> ExecuteAsync(string? search, string? categoria, bool bajoStock, int page, int pageSize, CancellationToken ct = default) { ValidatePage(page, pageSize); var result = await items.ListAsync(new(search, categoria, bajoStock, page, pageSize), ct); return new(result.Items.Select(InventoryItemDto.From).ToList(), result.TotalCount, result.Page, result.PageSize); } internal static void ValidatePage(int page, int pageSize) { if (page < 1 || pageSize is < 1 or > 100) throw new ArgumentException("La paginación es inválida."); } }
public sealed class ListStockMovementsUseCase(IStockMovementRepository movements) { public async Task<PagedInventoryResult<StockMovementDto>> ExecuteAsync(Guid id, int page, int pageSize, CancellationToken ct = default) { ListInventoryItemsUseCase.ValidatePage(page, pageSize); var result = await movements.ListByItemAsync(id, page, pageSize, ct); return new(result.Items.Select(StockMovementDto.From).ToList(), result.TotalCount, result.Page, result.PageSize); } }
